<?php
declare(strict_types=1);
session_start();
$config=__DIR__.'/config.local.php';$pdo=null;$error='';$notice='';$rows=[];$csrf=$_SESSION['demo_csrf']??=bin2hex(random_bytes(32));
if(is_file($config)){require $config;try{$pdo=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$pdo->exec("CREATE TABLE IF NOT EXISTS demo_records(id BIGINT AUTO_INCREMENT PRIMARY KEY,passenger_name VARCHAR(140) NOT NULL,dni CHAR(8) NOT NULL,origin VARCHAR(80) NOT NULL,destination VARCHAR(80) NOT NULL,departure_at DATETIME NOT NULL,seat_label VARCHAR(8) NOT NULL,amount DECIMAL(8,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}catch(Throwable $e){$error='No se pudo conectar con la base de datos. Revisa config.local.php.';}}
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$names=['María Torres','Luis Quispe','Ana Flores','Carlos Rojas','Rosa Mendoza','Diego Salazar','Lucía Vargas','José Huamán','Elena Castillo','Miguel Paredes'];$routes=[['Lima','Cusco',125.00],['Lima','Arequipa',95.00],['Lima','Trujillo',65.00],['Cusco','Arequipa',75.00]];
if($_SERVER['REQUEST_METHOD']==='POST'&&$pdo){if(!hash_equals($csrf,(string)($_POST['csrf']??''))){$error='La sesión venció. Recarga la página e inténtalo otra vez.';}else{try{$action=$_POST['action']??'';if($action==='generate'){$count=max(1,min(20,(int)($_POST['count']??1)));$stmt=$pdo->prepare('INSERT INTO demo_records(passenger_name,dni,origin,destination,departure_at,seat_label,amount) VALUES(?,?,?,?,?,?,?)');for($i=0;$i<$count;$i++){$route=$routes[array_rand($routes)];$stmt->execute([$names[array_rand($names)],(string)random_int(10000000,99999999),$route[0],$route[1],date('Y-m-d H:i:s',strtotime('+'.random_int(1,14).' days +'.random_int(6,22).' hours')),chr(65+random_int(0,9)).random_int(1,4),$route[2]]);}$notice="$count registro(s) de demostración guardado(s).";}elseif($action==='delete'){$q=$pdo->prepare('DELETE FROM demo_records WHERE id=?');$q->execute([(int)($_POST['id']??0)]);$notice='Registro de demostración eliminado.';}elseif($action==='clear'){$pdo->exec('DELETE FROM demo_records');$notice='Se borraron todos los registros de demostración.';}}catch(Throwable $e){$error='No se pudo guardar o borrar la información.';}}}
if($pdo){$rows=$pdo->query('SELECT * FROM demo_records ORDER BY created_at DESC,id DESC LIMIT 200')->fetchAll();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Simulador de datos · Ruta Norte</title><link rel="stylesheet" href="assets/app.css?v=20261028"></head><body><header class="top"><a class="brand" href="index.php"><span class="brand-icon">RN</span> RUTA<span>NORTE</span></a><nav><a href="index.php">Buscar viajes</a><a href="manifiesto.php">Embarque</a><a href="reportes.php">Reportes</a><a class="active" href="simulador.php">Simulador</a></nav><div class="user"><span class="avatar">DE</span><span>Datos de prueba<small>Simulación</small></span></div></header><main class="subpage"><div class="eyebrow"><i></i> HERRAMIENTA DE DEMOSTRACIÓN</div><h1>Simulador de información</h1><p class="muted">Genera datos ficticios, guárdalos para la demostración y elimínalos cuando quieras.</p><div class="notice demo-warning"><b>Estos registros son ficticios.</b> Se guardan en una tabla de demostración y no crean boletos, pagos, pasajeros ni ventas reales.</div><?php if($error):?><div class="notice"><?=h($error)?></div><?php endif;?><?php if($notice):?><div class="notice success"><?=h($notice)?></div><?php endif;?><?php if(!$pdo):?><div class="notice">Configura la base de datos para guardar los datos simulados.</div><?php else:?><section class="demo-panel"><form method="post" class="demo-controls"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="generate"><label>CANTIDAD<select name="count"><option value="1">1 registro</option><option value="5">5 registros</option><option value="10">10 registros</option><option value="20">20 registros</option></select></label><button class="search-btn">Generar y guardar</button></form><form method="post" onsubmit="return confirm('¿Borrar todos los registros ficticios guardados?')"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="clear"><button class="danger-btn" <?=!$rows?'disabled':''?>>Borrar todos los datos de prueba</button></form></section><div class="demo-count">Registros guardados: <b><?=count($rows)?></b> <small>(máximo 200 mostrados)</small></div><div class="manifest demo-table"><div class="manifest-row manifest-title"><span>Pasajero ficticio</span><span>DNI de prueba</span><span>Ruta</span><span>Fecha</span><span>Asiento</span><span>Monto</span><span>Acción</span></div><?php foreach($rows as $row):?><div class="manifest-row"><span><?=h($row['passenger_name'])?></span><span><?=h($row['dni'])?></span><span><?=h($row['origin'])?> → <?=h($row['destination'])?></span><span><?=h(date('d/m/Y H:i',strtotime($row['departure_at'])))?></span><span><?=h($row['seat_label'])?></span><span>S/ <?=number_format((float)$row['amount'],2)?></span><form method="post" onsubmit="return confirm('¿Eliminar este registro ficticio?')"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="danger-link">Borrar</button></form></div><?php endforeach;?><?php if(!$rows):?><div class="empty">Aún no hay datos de prueba guardados. Elige una cantidad y genera registros.</div><?php endif;?></div><?php endif;?></main><footer><span>© 2026 Ruta Norte</span><span>Simulador · solo datos de demostración</span><span>Los datos reales no se modifican</span></footer></body></html>
